package Vista;
import Modelo.*;import Persistencia.*;import javax.swing.*;import javax.swing.table.DefaultTableModel;import java.awt.*;import java.sql.*;import java.util.*;
public class Principal extends JFrame {
 private final AlumnoData ad=new AlumnoData();private final MateriaData md=new MateriaData();private final InscripcionData id=new InscripcionData();
 private final DefaultTableModel ta=tabla("ID","DNI","Apellido","Nombre","Activo"),tm=tabla("ID","Materia","Descripcion","Activo"),ti=tabla("ID","Alumno","Materia","Nota","Activo");
 private final JTable alumnos=new JTable(ta),materias=new JTable(tm),inscripciones=new JTable(ti);
 private final JTextField dni=new JTextField(9),apellido=new JTextField(12),nombre=new JTextField(12),materia=new JTextField(12),descripcion=new JTextField(14),nota=new JTextField(5);
 private final JComboBox<Alumno> ca=new JComboBox<>(),cn=new JComboBox<>();private final JComboBox<Materia> cm=new JComboBox<>(),cnotaMateria=new JComboBox<>();
 private final JRadioButton inscritas=new JRadioButton("Inscritas",true),noInscritas=new JRadioButton("No inscritas");
 private static DefaultTableModel tabla(String... cols){return new DefaultTableModel(cols,0){public boolean isCellEditable(int r,int c){return false;}};}
 private static void agregar(JPanel p,String etiqueta,JComponent c){p.add(new JLabel(etiqueta));p.add(c);}
 private static JButton boton(JPanel p,String titulo,Runnable r){JButton b=new JButton(titulo);b.addActionListener(e->{try{r.run();}catch(Exception x){JOptionPane.showMessageDialog(p,x.getMessage(),"Error",JOptionPane.ERROR_MESSAGE);}});p.add(b);return b;}
 private static JPanel panel(){return new JPanel(new FlowLayout(FlowLayout.LEFT));}
 private static int fila(JTable t){int i=t.getSelectedRow();if(i<0)throw new IllegalArgumentException("Selecciona una fila de la tabla");return Integer.parseInt(t.getValueAt(i,0).toString());}
 private static int numero(String s){return Integer.parseInt(s.trim());}
 private static void error(Exception ex){JOptionPane.showMessageDialog(null,ex.getMessage(),"Error",JOptionPane.ERROR_MESSAGE);}
 private static void run(SQLAction action){try{action.go();}catch(Exception e){error(e);}}
 private interface SQLAction{void go()throws Exception;}
 public Principal(){super("Proyecto Transversal - Parte 3");setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);setSize(1050,650);setLocationRelativeTo(null);JTabbedPane tabs=new JTabbedPane();tabs.add("Alumnos",vistaAlumnos());tabs.add("Materias",vistaMaterias());tabs.add("Inscripciones",vistaInscripciones());tabs.add("Cargar notas",vistaNotas());tabs.add("Listar inscripciones",vistaListado());setContentPane(tabs);run(()->refrescar());}
 private JPanel base(JTable t,JPanel arriba,JPanel abajo){JPanel p=new JPanel(new BorderLayout(4,4));p.add(arriba,BorderLayout.NORTH);p.add(new JScrollPane(t),BorderLayout.CENTER);p.add(abajo,BorderLayout.SOUTH);return p;}
 private JPanel vistaAlumnos(){JPanel arriba=panel(),abajo=panel();agregar(arriba,"DNI",dni);agregar(arriba,"Apellido",apellido);agregar(arriba,"Nombre",nombre);
 boton(abajo,"Insertar",()->run(()->{ad.insertar(new Alumno(0,numero(dni.getText()),apellido.getText(),nombre.getText(),true));refrescar();}));
 boton(abajo,"Actualizar",()->run(()->{ad.actualizar(new Alumno(fila(alumnos),numero(dni.getText()),apellido.getText(),nombre.getText(),true));refrescar();}));
 boton(abajo,"Borrar",()->run(()->{ad.borrar(fila(alumnos));refrescar();}));
 boton(abajo,"Baja logica",()->run(()->{ad.estado(fila(alumnos),false);refrescar();}));boton(abajo,"Alta logica",()->run(()->{ad.estado(fila(alumnos),true);refrescar();}));boton(abajo,"Mostrar todos",()->run(()->refrescar()));
 alumnos.getSelectionModel().addListSelectionListener(e->{if(!e.getValueIsAdjusting()&&alumnos.getSelectedRow()>=0){int r=alumnos.getSelectedRow();dni.setText(""+alumnos.getValueAt(r,1));apellido.setText(""+alumnos.getValueAt(r,2));nombre.setText(""+alumnos.getValueAt(r,3));}});return base(alumnos,arriba,abajo);}
 private JPanel vistaMaterias(){JPanel arriba=panel(),abajo=panel();agregar(arriba,"Materia",materia);agregar(arriba,"Descripcion",descripcion);
 boton(abajo,"Insertar",()->run(()->{md.insertar(new Materia(0,materia.getText(),descripcion.getText(),true));refrescar();}));
 boton(abajo,"Actualizar",()->run(()->{md.actualizar(new Materia(fila(materias),materia.getText(),descripcion.getText(),true));refrescar();}));
 boton(abajo,"Borrar",()->run(()->{md.borrar(fila(materias));refrescar();}));boton(abajo,"Baja logica",()->run(()->{md.estado(fila(materias),false);refrescar();}));boton(abajo,"Alta logica",()->run(()->{md.estado(fila(materias),true);refrescar();}));boton(abajo,"Mostrar todas",()->run(()->refrescar()));
 materias.getSelectionModel().addListSelectionListener(e->{if(!e.getValueIsAdjusting()&&materias.getSelectedRow()>=0){int r=materias.getSelectedRow();materia.setText(""+materias.getValueAt(r,1));descripcion.setText(""+materias.getValueAt(r,2));}});return base(materias,arriba,abajo);}
 private JPanel vistaInscripciones(){JPanel p=new JPanel(new BorderLayout());JPanel arriba=panel(),abajo=panel();agregar(arriba,"Alumno",ca);agregar(arriba,"Materia",cm);boton(abajo,"Inscribir",()->run(()->{id.inscribir(((Alumno)ca.getSelectedItem()).getIdAlumno(),((Materia)cm.getSelectedItem()).getIdMateria());refrescar();}));boton(abajo,"Anular inscripcion",()->run(()->{id.anular(((Alumno)ca.getSelectedItem()).getIdAlumno(),((Materia)cm.getSelectedItem()).getIdMateria());refrescar();}));boton(abajo,"Actualizar",()->run(()->refrescar()));p.add(arriba,BorderLayout.NORTH);p.add(new JScrollPane(inscripciones),BorderLayout.CENTER);p.add(abajo,BorderLayout.SOUTH);return p;}
 private JPanel vistaNotas(){JPanel p=new JPanel(new BorderLayout());JPanel arriba=panel(),abajo=panel();agregar(arriba,"Alumno",cn);agregar(arriba,"Materia",cnotaMateria);agregar(arriba,"Nota (0-10)",nota);boton(abajo,"Cargar nota",()->run(()->{int a=((Alumno)cn.getSelectedItem()).getIdAlumno(),m=((Materia)cnotaMateria.getSelectedItem()).getIdMateria();int ins=-1;for(Inscripcion i:id.listar())if(i.getIdAlumno()==a&&i.getIdMateria()==m&&i.isActivo())ins=i.getIdInscripcion();if(ins<0)throw new IllegalArgumentException("El alumno no tiene una inscripcion activa en esta materia");id.cargarNota(ins,Double.parseDouble(nota.getText().replace(',','.')));refrescar();}));p.add(arriba,BorderLayout.NORTH);p.add(new JScrollPane(new JTable(ti)),BorderLayout.CENTER);p.add(abajo,BorderLayout.SOUTH);return p;}
 private JPanel vistaListado(){DefaultTableModel modelo=tabla("Materia","Estado","Alumno","Nota");JTable lista=new JTable(modelo);JPanel p=new JPanel(new BorderLayout());JPanel arriba=panel();JComboBox<Materia> filtro=new JComboBox<>();agregar(arriba,"Materia",filtro);ButtonGroup bg=new ButtonGroup();bg.add(inscritas);bg.add(noInscritas);arriba.add(inscritas);arriba.add(noInscritas);
 Runnable cargar=()->run(()->{modelo.setRowCount(0);Materia m=(Materia)filtro.getSelectedItem();if(m==null)return;Set<Integer> activos=new HashSet<>();Map<Integer,Double> notas=new HashMap<>();for(Inscripcion i:id.listar())if(i.getIdMateria()==m.getIdMateria()&&i.isActivo()){activos.add(i.getIdAlumno());notas.put(i.getIdAlumno(),i.getNota());}for(Alumno a:ad.listar())if(a.isActivo()&&(inscritas.isSelected()==activos.contains(a.getIdAlumno())))modelo.addRow(new Object[]{m.getNombre(),inscritas.isSelected()?"Inscrita":"No inscrita",a.toString(),notas.get(a.getIdAlumno())});});
 boton(arriba,"Consultar",cargar);boton(arriba,"Actualizar materias",()->run(()->{filtro.removeAllItems();for(Materia m:md.listar())if(m.isActivo())filtro.addItem(m);cargar.run();}));p.add(arriba,BorderLayout.NORTH);p.add(new JScrollPane(lista),BorderLayout.CENTER);return p;}
 private void refrescar()throws SQLException{ta.setRowCount(0);tm.setRowCount(0);ti.setRowCount(0);ca.removeAllItems();cn.removeAllItems();cm.removeAllItems();cnotaMateria.removeAllItems();Map<Integer,String> as=new HashMap<>(),ms=new HashMap<>();for(Alumno a:ad.listar()){ta.addRow(new Object[]{a.getIdAlumno(),a.getDni(),a.getApellido(),a.getNombre(),a.isActivo()});as.put(a.getIdAlumno(),a.toString());if(a.isActivo()){ca.addItem(a);cn.addItem(a);}}for(Materia m:md.listar()){tm.addRow(new Object[]{m.getIdMateria(),m.getNombre(),m.getDescripcion(),m.isActivo()});ms.put(m.getIdMateria(),m.getNombre());if(m.isActivo()){cm.addItem(m);cnotaMateria.addItem(m);}}for(Inscripcion i:id.listar())ti.addRow(new Object[]{i.getIdInscripcion(),as.get(i.getIdAlumno()),ms.get(i.getIdMateria()),i.getNota(),i.isActivo()});}
 public static void main(String[] args){SwingUtilities.invokeLater(()->new Principal().setVisible(true));}
}
